      S('rect', { x: x(0), y, width: x(m.pLive) - x(0), height: 11, fill: C.amber, rx: 2 }, svg);
      S('rect', { x: x(0), y: y + 13, width: Math.max(1, x(m.pLiveDilemma) - x(0)), height: 5, fill: '#777', rx: 1 }, svg);
